      supplier.supplierName.toLowerCase().includes(lowercasedSearchText) ||
      (supplier.contactName?.toLowerCase().includes(lowercasedSearchText)) ||
      (supplier.email?.toLowerCase().includes(lowercasedSearchText))
    );
    setFilteredSuppliers(filtered);
  }, [searchText, suppliers]);

  const handleSearchChange = (e: CustomEvent<SearchbarInputEventDetail>) => {
    setSearchText(e.detail.value!);
  };

  const handleFieldChange = (key: keyof typeof formState, value: string | boolean) => {
    setFormState(prev => ({ ...prev, [key]: value }));
    if (key === 'supplierName' && typeof value === 'string' && value.trim()) {
      setFormErrors(prev => ({ ...prev, supplierName: '' }));
    }
    if (key === 'email' && typeof value === 'string' && (/^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/.test(value) || !value.trim())) {
      setFormErrors(prev => ({ ...prev, email: '' }));
    }
  };

